import { vec3 } from 'gl-matrix';
import { utilities as csUtils } from '@cornerstonejs/core';
import { getShapeIndexBounds } from '../../../../utilities/sampleAreaAnnotationVoxels.js';
export const brushFillLog = csUtils.logger.toolsLog.getLogger('segmentation', 'brushVoxelSlab');
const { createEllipseShape, createRectangleShape, createUnionShape, getSlabEpsilon, getSlabHalfWidth, getVoxelThicknessAlongNormal, isSlabDepthLowInclusive, iterateVoxelsInShape, resolveReferencePlaneThickness, signedDistanceToPlane, } = csUtils.voxelSlab;
function volumeFromImageData(imageData) {
    return {
        dimensions: imageData.getDimensions(),
        direction: imageData.getDirection(),
        spacing: imageData.getSpacing(),
        origin: imageData.getOrigin(),
    };
}
function getViewRight(viewUp, viewPlaneNormal) {
    const right = vec3.cross(vec3.create(), viewUp, viewPlaneNormal);
    return vec3.normalize(right, right);
}
function densifyStrokeCenters(centers, stepWorld) {
    if (centers.length <= 1 || !(stepWorld > 0)) {
        return centers;
    }
    const dense = [centers[0]];
    for (let index = 1; index < centers.length; index++) {
        const from = centers[index - 1];
        const to = centers[index];
        const delta = [to[0] - from[0], to[1] - from[1], to[2] - from[2]];
        const length = Math.hypot(delta[0], delta[1], delta[2]);
        const steps = Math.max(1, Math.ceil(length / stepWorld));
        for (let step = 1; step <= steps; step++) {
            const t = step / steps;
            dense.push([
                from[0] + delta[0] * t,
                from[1] + delta[1] * t,
                from[2] + delta[2] * t,
            ]);
        }
    }
    return dense;
}
function buildBrushFill({ segmentationImageData, planePoint, viewPlaneNormal, centersWorld, boundsMargin, viewThicknessWorld, createShape, }) {
    if (!centersWorld.length) {
        return null;
    }
    const volume = volumeFromImageData(segmentationImageData);
    const voxelThickness = getVoxelThicknessAlongNormal(volume, viewPlaneNormal);
    const shapes = centersWorld
        .map((centerWorld) => createShape({ volume, planePoint, viewPlaneNormal, centerWorld }))
        .filter(Boolean);
    if (!shapes.length) {
        return null;
    }
    const shape = createUnionShape(shapes);
    const requiredThickness = shape.getRequiredThickness();
    const carriesOwnDepth = requiredThickness > 0;
    const depthCoverage = carriesOwnDepth
        ? 'overlapping'
        : 'centerInside';
    const thicknessWorld = resolveReferencePlaneThickness(carriesOwnDepth ? requiredThickness : viewThicknessWorld, voxelThickness);
    return {
        volume,
        planePoint,
        viewPlaneNormal,
        thicknessWorld,
        depthCoverage,
        bounds: getShapeIndexBounds(centersWorld, volume, segmentationImageData, viewPlaneNormal, getSlabHalfWidth(thicknessWorld, voxelThickness, depthCoverage), boundsMargin),
        shape,
    };
}
export function createCircleBrushFill(operationData) {
    const { segmentationImageData, viewUp, viewPlaneNormal, centerWorld, xRadius, yRadius, viewThicknessWorld, } = operationData;
    if (!(xRadius > 0) || !(yRadius > 0)) {
        return null;
    }
    const viewRight = getViewRight(viewUp, viewPlaneNormal);
    const centers = operationData.strokeCentersWorld?.length
        ? operationData.strokeCentersWorld
        : [centerWorld];
    return buildBrushFill({
        segmentationImageData,
        planePoint: centerWorld,
        viewPlaneNormal,
        centersWorld: densifyStrokeCenters(centers, Math.min(xRadius, yRadius) / 2),
        boundsMargin: Math.max(xRadius, yRadius),
        viewThicknessWorld,
        createShape: ({ volume, planePoint, centerWorld: center }) => createEllipseShape({
            volume,
            planePoint,
            viewPlaneNormal,
            centerWorld: center,
            majorAxis: viewRight,
            majorRadius: xRadius,
            minorRadius: yRadius,
        }),
    });
}
export function createSphereBrushFill(operationData) {
    const { segmentationImageData, viewUp, viewPlaneNormal, centerWorld, xRadius, yRadius, } = operationData;
    if (!(xRadius > 0) || !(yRadius > 0)) {
        return null;
    }
    const depthRadius = Math.max(xRadius, yRadius);
    const viewRight = getViewRight(viewUp, viewPlaneNormal);
    const centers = operationData.strokeCentersWorld?.length
        ? operationData.strokeCentersWorld
        : [centerWorld];
    return buildBrushFill({
        segmentationImageData,
        planePoint: centerWorld,
        viewPlaneNormal,
        centersWorld: densifyStrokeCenters(centers, Math.min(xRadius, yRadius) / 2),
        boundsMargin: depthRadius,
        createShape: ({ volume, planePoint, centerWorld: center }) => createEllipseShape({
            volume,
            planePoint,
            viewPlaneNormal,
            centerWorld: center,
            majorAxis: viewRight,
            majorRadius: xRadius,
            minorRadius: yRadius,
            depthRadius,
        }),
    });
}
export function createRectangleBrushFill(operationData) {
    const { segmentationImageData, cornersWorld } = operationData;
    if (cornersWorld.length < 4) {
        return null;
    }
    const [p0, p1, , p3] = cornersWorld;
    const majorAxis = vec3.sub(vec3.create(), p1, p0);
    const minorAxis = vec3.sub(vec3.create(), p3, p0);
    const majorHalfLength = vec3.length(majorAxis) / 2;
    const minorHalfLength = vec3.length(minorAxis) / 2;
    if (!(majorHalfLength > 0) || !(minorHalfLength > 0)) {
        return null;
    }
    const normal = vec3.cross(vec3.create(), majorAxis, minorAxis);
    if (!(vec3.squaredLength(normal) > 0)) {
        if (!operationData.viewPlaneNormal) {
            return null;
        }
        vec3.copy(normal, operationData.viewPlaneNormal);
    }
    vec3.normalize(normal, normal);
    const center = vec3.lerp(vec3.create(), p0, cornersWorld[2], 0.5);
    return buildBrushFill({
        segmentationImageData,
        planePoint: center,
        viewPlaneNormal: normal,
        centersWorld: [center],
        boundsMargin: Math.hypot(majorHalfLength, minorHalfLength),
        createShape: ({ volume, planePoint, viewPlaneNormal, centerWorld }) => createRectangleShape({
            volume,
            planePoint,
            viewPlaneNormal,
            centerWorld,
            majorAxis: majorAxis,
            majorHalfLength,
            minorHalfLength,
        }),
    });
}
export function createBrushFillPredicate(fill, imageData) {
    const { planePoint, viewPlaneNormal, shape } = fill;
    const voxelThickness = getVoxelThicknessAlongNormal(fill.volume, viewPlaneNormal);
    const halfWidth = getSlabHalfWidth(fill.thicknessWorld, voxelThickness, fill.depthCoverage);
    const epsilon = getSlabEpsilon(voxelThickness);
    const halfOpen = isSlabDepthLowInclusive(fill.depthCoverage);
    const depthLow = halfOpen ? -halfWidth - epsilon : -halfWidth + epsilon;
    const depthHigh = halfWidth - epsilon;
    const scratch = [0, 0, 0];
    return (pointLPS, pointIJK) => {
        let world = pointLPS;
        if (!world) {
            if (!pointIJK || !imageData) {
                return false;
            }
            world = imageData.indexToWorld(pointIJK, scratch);
        }
        const depth = signedDistanceToPlane(world, planePoint, viewPlaneNormal);
        const withinDepth = halfOpen
            ? depth >= depthLow && depth < depthHigh
            : depth > depthLow && depth < depthHigh;
        return withinDepth && shape.containsPoint(world);
    };
}
export function applyBrushFill(operationData, fill) {
    if (!fill) {
        return;
    }
    operationData.brushVoxelSlabFill = fill;
    operationData.isInObject = createBrushFillPredicate(fill, operationData.segmentationImageData);
    operationData.isInObjectBoundsIJK = fill.bounds;
}
export function forEachBrushFillVoxel(fill, voxelManager, callback) {
    const iteration = iterateVoxelsInShape({
        volume: fill.volume,
        planePoint: fill.planePoint,
        viewPlaneNormal: fill.viewPlaneNormal,
        referencePlaneThickness: fill.thicknessWorld,
        depthCoverage: fill.depthCoverage,
        bounds: fill.bounds,
        getShapeRuns: fill.shape.getRuns,
    });
    const debug = (brushFillLog.getLevel?.() ?? 5) <= 1;
    const depths = [];
    let minDepth = Infinity;
    let maxDepth = -Infinity;
    let painted = 0;
    for (const { ijk, center } of iteration) {
        if (debug) {
            const depth = (center[0] - fill.planePoint[0]) * fill.viewPlaneNormal[0] +
                (center[1] - fill.planePoint[1]) * fill.viewPlaneNormal[1] +
                (center[2] - fill.planePoint[2]) * fill.viewPlaneNormal[2];
            depths.push(depth);
            minDepth = Math.min(minDepth, depth);
            maxDepth = Math.max(maxDepth, depth);
        }
        painted++;
        const pointIJK = [ijk[0], ijk[1], ijk[2]];
        const index = voxelManager.toIndex(pointIJK);
        callback({
            value: voxelManager.getAtIndex(index),
            index,
            pointIJK,
            pointLPS: [center[0], center[1], center[2]],
        });
    }
    if (!debug) {
        return;
    }
    if (!painted) {
        brushFillLog.debug('brush fill painted=0');
        return;
    }
    const voxelThickness = getVoxelThicknessAlongNormal(fill.volume, fill.viewPlaneNormal);
    const layers = new Set(depths.map((depth) => Math.round((depth / voxelThickness) * 10) / 10));
    const sorted = [...layers].sort((a, b) => a - b);
    const span = (maxDepth - minDepth) / voxelThickness;
    const halfWidth = getSlabHalfWidth(fill.thicknessWorld, voxelThickness, fill.depthCoverage);
    brushFillLog.debug(`brush fill painted=${painted} T_v=${voxelThickness.toFixed(4)} ` +
        `coverage=${fill.depthCoverage} ` +
        `halfWidth=${halfWidth.toFixed(4)} ` +
        `halfWidth/T_v=${(halfWidth / voxelThickness).toFixed(4)} ` +
        `depthSpanInVoxels=${span.toFixed(4)} ` +
        `distinctLayers=${sorted.length} ` +
        `${span < 1 ? 'ONE PLANE' : 'MORE THAN ONE PLANE'}`, {
        minDepth,
        maxDepth,
        layersInVoxels: sorted.length <= 24 ? sorted : `${sorted.length} values`,
        planePoint: fill.planePoint,
        viewPlaneNormal: fill.viewPlaneNormal,
    });
}
